#!/usr/bin/env python3
"""Generate the firmware's embedded setup page from frontend/setup.html."""

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parent
SOURCE = ROOT / "frontend" / "setup.html"
OUTPUT = ROOT / "lib" / "portal" / "views" / "setup_page.h"


def render(source: str) -> str:
    delimiter = "TOBUY_PAGE"
    if f"){delimiter}\"" in source:
        raise ValueError("HTML contains the C++ raw-string delimiter")
    return (
        "#pragma once\n\n"
        "#include <Arduino.h>\n\n"
        "// Generated by build_views.py; edit frontend/setup.html instead.\n"
        f'const char setup_page[] PROGMEM = R"{delimiter}({source}){delimiter}";\n'
    )


def generate() -> None:
    generated = render(SOURCE.read_text(encoding="utf-8"))
    if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != generated:
        OUTPUT.parent.mkdir(parents=True, exist_ok=True)
        OUTPUT.write_text(generated, encoding="utf-8")
        print(f"Generated {OUTPUT}")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the generated header is stale")
    args = parser.parse_args()
    if args.check:
        generated = render(SOURCE.read_text(encoding="utf-8"))
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != generated:
            parser.exit(1, f"{OUTPUT} is missing or stale; run python3 build_views.py\n")
        print(f"Verified {OUTPUT}")
    else:
        generate()


if __name__ == "__main__":
    main()
